const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
setTimeout(()=>document.body.classList.add('app-ready'),1500);
let store={};try{store=JSON.parse(localStorage.getItem('gymflow-v3')||'null')||{};if(!store.gyms){const legacy=JSON.parse(localStorage.getItem('gymflow-v2')||'{}')||{};store={gymId:'studio',gyms:{studio:legacy}}}}catch{store={}};
let gymId=getGym(store.gymId).id,records=store.gyms||{},gym=getGym(gymId),equipment=equipmentForGym(gymId),presets=gym.presets;
const raw=id=>equipment.find(e=>e.id===id),byId=id=>machine(raw(id));let mode='full',custom=[],customMeta={},done={},selected='',currentFloor=0,zone='all',search='',restEnd=0,started=false,map=null,storageFailed=false,fullRoute=false;
const builtinPresets=()=>presets.filter(p=>p.category!=='trainer');
const trainerCertifiedPresets=()=>presets.filter(p=>p.category==='trainer');
function accessiblePresets(){const builtin=builtinPresets();return subscription.can('library')?[...builtin,...trainerCertifiedPresets()]:builtin.slice(0,2)}
const isAccessiblePreset=id=>id==='custom'||accessiblePresets().some(p=>p.id===id);
function loadGymState(){const state=records[gymId]||{};mode=isAccessiblePreset(state.mode)?state.mode:(accessiblePresets()[0]?.id||'full');custom=normalizeSteps(state.custom,gymId);customMeta=state.customMeta&&typeof state.customMeta==='object'?state.customMeta:{};done=state.done&&typeof state.done==='object'?state.done:{};selected=(mode==='custom'?custom[0]?.id:presets.find(p=>p.id===mode).ids[0])||equipment[0].id;currentFloor=raw(selected).floor;zone='all';search='';restEnd=0;started=false}
loadGymState();
const makeStep=id=>{const e=raw(id);return{id,sets:e.sets,reps:e.reps,rest:e.rest}};const getPlan=()=>mode==='custom'?custom:presets.find(p=>p.id===mode).ids.map(makeStep);const key=id=>mode+':'+id;const checks=s=>Array.from({length:s.sets},(_,i)=>!!done[key(s.id)]?.[i]);const isDone=id=>{const s=getPlan().find(s=>s.id===id);return s?checks(s).every(Boolean):false};
